parameters.jsCode:
// Role is NEVER taken from message text. body.role / body.tenant_id are ignored.
// Tenant comes ONLY from the channels lookup (previous node).
// Role comes ONLY from tenant_members via the Identify query (member_role).
// Suspension/balance come ONLY from the Identify query (022 RPCs).
// Message fields come ONLY from the Webhook node.
// Zero-row lookup output ({"success": true}, no tenant_id) = no channel.
const webhook = $('Webhook').first().json;
const body = webhook.body || webhook;
const row = $input.first().json;
const tenantId = row.tenant_id || null;
let gate = 'proceed';
let role = row.member_role || 'customer';
let suspended = false;
let suspend_reason = null;
if (!tenantId) {
  gate = 'blocked_no_channel';
} else if (row.status === 'paused' || row.status === 'cancelled') {
  gate = 'blocked_paused';
} else if (row.is_suspended === true) {
  gate = 'blocked_suspended'; suspended = true; suspend_reason = 'suspended';
} else if (role === 'customer' && row.balance !== null && row.balance !== undefined && Number(row.balance) <= 0) {
  gate = 'blocked_no_balance'; suspended = true; suspend_reason = 'no_balance';
}
return [{ json: {
  provider: body.provider,
  external_id: body.external_id,
  channel: body.channel || body.provider,
  channel_user_id: body.channel_user_id,
  message_id: body.message_id || null,
  raw_message: body.payload?.text || body.message || '',
  tenant_id: tenantId,
  sector_code: row.sector_code || null,
  business_name: row.business_name || null,
  tenant_status: row.status || null,
  role: role,
  gate: gate,
  suspended: suspended,
  suspend_reason: suspend_reason,
  verdict: gate === 'proceed' ? null : gate
} }];

function normalizeArabic(t) {
  if (!t) return '';
  return String(t)
    .replace(/[أإآ]/g, 'ا')
    .replace(/ة/g, 'ه')
    .replace(/ى/g, 'ي')
    .replace(/ئ/g, 'ي')
    .replace(/ؤ/g, 'و')
    .replace(/ـ+/g, '')
    .replace(/[ً-ْ]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

// SINGLE copy of normalizeArabic in the whole workflow. No other node
// re-implements it; later nodes use normalized_message from this node.
// Map is 7 letters in the SQL translate form: from 'أإآةىئؤ' to
// 'اااهييو';
// standalone hamza ء is left as-is. Keywords below are built from the
// normalized text, never from the raw text.
const src = $input.first().json;
const normalized = normalizeArabic(src.raw_message || '');
const stop = new Set(['انا', 'عايز', 'عايزة', 'اريد', 'كم', 'سعر', 'في', 'من', 'ايه', 'ما', 'هل', 'لو', 'عندكم', 'عندك', 'ابغى', 'ابي', 'ممكن', 'سلام', 'عليكم', 'وعليكم', 'السلام', 'اهلا', 'مرحبا', 'صباح', 'مساء', 'الخير', 'هلا', 'يا', 'ال', 'ابعتلي', 'ابعت', 'وريني', 'ورينا', 'هات', 'سمحت', 'فضلك', 'اعرف', 'المتاح', 'متاح', 'اسعار', 'والسعر', 'والاسعار', 'كل', 'جميع', 'رسائل', 'وقسمه', 'قسمه', 'قسمها', 'طويل', 'بالاسعار', 'اسعارها', 'واسعارها', 'كله', 'كلها', 'على'].map(normalizeArabic));
const words = normalized.split(' ').filter(function (w) { return w.length >= 2 && !stop.has(w); });

// Search keywords only (stored names are untouched): strip punctuation, then
// strip the definite-article prefix 'ال' (query side only). Do NOT strip
// ب/و/ف/ل prefixes: e.g. 'وليمة' is a real word, not a prefix.
const pluralToSingular = {'اراضي': 'ارض', 'قطع': 'قطعه', 'شقق': 'شقه', 'ساندوتشات': 'ساندوتش', 'سندوتشات': 'ساندوتش', 'عيادات': 'عياده', 'دكاتره': 'دكتور'};
const baseKeywords = [];
words.forEach(function (w) {
  var k = w.replace(/[^\p{L}\p{N}\s-]/gu, '');
  if (k.startsWith('ال') && k.length > 2) { k = k.slice(2); }
  if (pluralToSingular[k]) { k = pluralToSingular[k]; }
  if (k.length >= 1 && baseKeywords.indexOf(k) === -1) { baseKeywords.push(k); }
});
const keywords = baseKeywords;
function escapeRegex(s) { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

// Classification (D1, GENERAL FIX 2026-11-02): generic words are the
// normalized forms of the collection-word list (menu/list words + land
// words, as in the old is_coll regex, normalized: قائمة/قايمة -> قايمه,
// لائحه -> لايحه, مينيو kept distinct from منيو). subset_terms = the rest.
// collection_intent is true ONLY when no subset term exists and at
// least one generic term exists. Request verbs and politeness markers
// are stop-words above, so 'ابعتلي القايمه' is a pure collection ask.
const genericSet = new Set(['قايمه', 'منيو', 'مينيو', 'لايحه', 'لسته', 'اصناف', 'اطباق', 'وجبات', 'اكلات', 'اكل', 'منتجات', 'تشكيله', 'ارض', 'اراضي', 'طعام', 'ماكولات', 'menu'].map(normalizeArabic));
const generic_terms = [];
const subset_terms = [];
const collectionAnchor = baseKeywords.some(function(k) { return genericSet.has(k); });
const listQualifiers = new Set(['كامل','كامله','الكامل','بالكامل','كل','جميع','قسمه','قسمها','رسائل','طويل','اسعار','الاسعار','بالاسعار','والاسعار','واسعارها','اسعارها','فئات','الفئات','اقسام','الاقسام','مجموعات','بالترتيب'].map(normalizeArabic));
baseKeywords.forEach(function (k) {
  if (genericSet.has(k)) { generic_terms.push(k); }
  else if (!(collectionAnchor && (listQualifiers.has(k) || listQualifiers.has(k.replace(/^[وب]+/,''))))) { subset_terms.push(k); }
});
const collection_intent = subset_terms.length === 0 && generic_terms.length > 0;

// Expansion (D1): one word -> its explicit plural/singular forms, both
// directions, NORMALIZED forms only (normalization already unifies
// ة/ه, ى/ي, أ/ا variants, so no ة-forms are emitted: they could never
// match the normalized data side). keyword_set holds the EXPANDED
// SUBSET terms only: generic words never pollute matching.
const expandMap = {'ارض': ['اراضي'], 'اراضي': ['ارض'], 'قطع': ['قطعه'], 'قطعه': ['قطع']};
const keyword_set = [];
subset_terms.forEach(function (k) {
  if (keyword_set.indexOf(k) === -1) { keyword_set.push(k); }
  (expandMap[k] || []).forEach(function (f) { if (keyword_set.indexOf(f) === -1) { keyword_set.push(f); } });
});
const search_terms = keyword_set.join('|');

// intent_key: GENERIC (2026-10-31, approved design). The normalized
// question text itself is the key — any repeated question, any sector.
// Normalization collapses variants onto one form (قائمة/قائمه -> قايمه,
// خدمة -> خدمه), so the same question asked in any variant hits one key.
// intent_key: GENERIC — the normalized question itself, ANY sector.
// Same normalized question + same tenant + same data_hash => cache hit.
// Empty normalized text => null (no key, no cache write/lookup).
// Tenant isolation comes from tenant_id in the cache key, not from here.
const speakerRole = src.role || 'customer';
const intent_key = normalized ? (speakerRole === 'owner' ? normalized + '‖owner' : normalized) : null;

return [{ json: Object.assign({}, src, {
  normalized_message: normalized,
  keywords: keywords,
  keyword_set: keyword_set,
  search_terms: search_terms,
  subset_terms: subset_terms,
  generic_terms: generic_terms,
  // SQL contract: $4 is compared as TEXT ($4 = 'true') through the
  // comma-joined queryReplacement string, so emit the 'true'/'false' string.
  collection_intent: collection_intent ? 'true' : 'false',
  search_regex: keywords.map(escapeRegex).join('|'),
  intent_key: intent_key
}) }];

// BRAIN REPLACEMENT 2026-10-30: sector voice comes ONLY from the sector pack in Load Tenant Data (pack inserted as-is). No inline sector lookup remains in this node.
// MERGE 2026-10-30: projectIndex carries name + area + city + attributes; one hard anti-inference rule added to the base honesty rules.
// STAGE 2 2026-10-30: owner voice block inserted after the pack section and before the memory section; voice comes ONLY from tenant_voice_settings via Load Tenant Data (voice inserted as-is, no dialect branches).
const s = $('Load Tenant Data').first().json;
const speakerRole = ($('Identify Role and Gate').first().json || {}).role || 'customer';
const system = "You serve this tenant only. The attached rows are tenant-scoped evidence for this question. Read the scope and truncation metadata before making completeness claims. Answer the customer's actual request from them using the sector pack's structure and voice.\nYou are the Barqlo sales brain. Reply in clear Arabic. Never invent a price, count, date, or attribute. Use ONLY the attached tenant data. Company-wide financial terms may be stated only from the active Policies block. An item-specific price, down payment, installment plan, reservation amount, or discount may be stated only from that same attached item row, clearly labeled as item details rather than company-wide policy. State the item value beside its field name in a readable line when it is supported by the row. Never infer, round, convert currency, or apply one item’s terms to another item. If an active company policy conflicts with an item field, do not quote the conflicting item number as approved; state the policy value and refer the discrepancy to the owner. If neither an active policy nor the requested item row supplies a figure, state that the figure is missing. Never say a fee or discount is zero unless zero is explicit in the attached source. If information is missing from the attached data, say so honestly and do not complete it by guessing. Never mention another tenant, tenant ids, or internal identifiers. Output JSON ONLY with fields reply_text, cited_items (item id + field + value), confidence (high/low), dialogue_state (small object tracking the customer goal, customer-provided slots, and next missing field) TOTALS CITATIONS: cite tenant totals ONLY as {id: 'totals', field, value} where field is one of the keys in the Totals block shown above and value equals the totals value exactly. NEVER cite a totals value under a row id or row name. NEVER rephrase a totals figure with a currency word. Totals stated in prose without a citation entry are allowed; totals cited with a wrong value or a wrong field will fail verification.. If you cannot cite from attached data, set confidence to low and declare the gap. A short message naming one item IS a question about that item – answer it directly, and never claim the message did not arrive when its text is present in the request. When relevant_items, projects, or project_index rows are attached in the prompt, never state that their details are missing, unattached, or unavailable; a detail may be declared missing only for a specific field that is genuinely absent from the attached rows themselves, for example total price may be declared missing when only price-per-sqm is present. Land-price rule: for land rows where price is null, use price_per_sqm; show سعر المتر + area_sqm; never present a per-sqm figure as a total price; never compute an unlabeled total from per-sqm and area. Rent rule: for rows with listing=rent, label the price إيجار شهري and never present it as a sale price. Filtered-list exclusion rule: when a list is delivered filtered by an attribute (for example a doctor name), name the excluded class explicitly in the reply (for example, the services of أي طبيب آخر are excluded). Status rule (general, data-driven, not sector logic): EVERY row that has a status field MUST show its status in its line, in Arabic (available → متاح, booked → محجوز, sold → مباع); lands lines = name + per-sqm price + area + status; units lines = their existing attributes + status; rows without a status field (menu items, services) are unaffected. Never present a clinic-wide working-days value as a specific doctor's attendance days; never derive a floor from a unit code. Gap truth rule: mention a missing detail only when the customer explicitly asks for that exact detail and no eligible attached row supplies it. Name the exact absent field once in natural Arabic; do not write a generic «ملاحظة شفافية» template, do not call an existing item or its details missing as a whole, and never add missing-data notices for unasked fields. Catalog status is not a live stock count or appointment slot: say the item is listed as available when status says available, but do not promise current quantity, immediate fulfillment, or a confirmed booking without a recorded availability check. Presentation rule: answer the requested question first. Use short paragraphs and blank lines. For several matching rows, use one compact bullet per row; for a single named row, show a clear short heading and only the fields relevant to the question. Follow the active sector pack for field order, terminology, and next step. Never list the same row twice or mention the whole catalog count unless the customer requests a list or a total.";
const roleSection = speakerRole === 'owner'
  ? "\nSpeaker: the person you are speaking with is the business OWNER of this tenant. Address them directly as the owner: concise, operational tone, no customer-facing sales phrasing, and never pretend they are a customer. You may state internal facts (totals, statuses) plainly."
  : "\nSpeaker: the person you are speaking with is a CUSTOMER. Use the sales voice from the sector pack.";
const projectIndex = (s.project_index || []).map(function(p) { return {name: p.name, area: p.area, city: p.city, attributes: p.attributes};});
const totalProjects = s.totals && s.totals.projects_count!== undefined? s.totals.projects_count: projectIndex.length;
const normNode = $('Normalize Arabic').first().json;
const currentMessage = normNode.normalized_message || '';
const currentRaw = normNode.raw_message || '';
// Prompt trimming: remove the current message from history (it already appears under CURRENT MESSAGE below), keep the last 12 otherwise, oldest first. Policies are left as they are.
const allHistory = (s.history || []).filter(function(h) { return h && h.content; });
const lastTurn = allHistory[allHistory.length - 1];
const cleanHistory = (lastTurn && lastTurn.sender_role !== 'assistant' && (lastTurn.content === currentMessage || lastTurn.content === currentRaw) ? allHistory.slice(0, -1) : allHistory).slice(-10);
const lastAssistant = [...cleanHistory].reverse().find(function(h) { return h.sender_role === 'assistant' || h.sender_role === 'brain'; });
const lastCustomer = [...cleanHistory].reverse().find(function(h) { return h.sender_role === 'customer'; });
// Keep customer-provided identity and the active request across turns before asking the model.
const previousState = s.dialogue_state && typeof s.dialogue_state === 'object' && !Array.isArray(s.dialogue_state) ? s.dialogue_state : {};
const previousSlots = previousState.slots && typeof previousState.slots === 'object' && !Array.isArray(previousState.slots) ? previousState.slots : {};
const freshGoal = /(?:طلب|بحث|حجز|اوردر|أوردر)\s+جديد|نبدأ من جديد|ابدأ من جديد|غيرت رأيي|الغي الطلب|إلغي الطلب/.test(currentRaw || currentMessage) || /(?:عايز|محتاج|حابب|اريد|أريد)\s+(?:ا|أ)?(?:طلب|اطلب|أطلب|احجز|أحجز)/.test(currentRaw || currentMessage);
const carriedSlots = freshGoal ? Object.fromEntries(Object.entries(previousSlots).filter(([key]) => ['name','customer_name','phone','phone_candidate'].includes(key))) : {...previousSlots};
const rawTurn = String(currentRaw || currentMessage || '');
const phoneFound = rawTurn.match(/(?:^|[^0-9])(01[0-9]{8,9})(?![0-9])/);
if (phoneFound) {
  if (phoneFound[1].length === 11) { carriedSlots.phone = phoneFound[1]; delete carriedSlots.phone_candidate; }
  else carriedSlots.phone_candidate = phoneFound[1];
}
const explicitName = rawTurn.match(/(?:^|[\s،])(?:اسمي|اسمى|انا اسمي|أنا اسمي)\s+([^\n،,.]{2,70})/);
if (explicitName) {
  const personName = explicitName[1].split(/\s+(?:ورقمي|رقمي|يوم|الساعة|وهستلم|هستلم|ومحتاج|محتاج|وعايز|عايز)/)[0].replace(/\s+/g,' ').trim();
  if (personName && !/^(معاك|عندك|ايه|إيه|فين)/.test(personName)) { carriedSlots.name = personName.slice(0,80); carriedSlots.customer_name = personName.slice(0,80); }
}
const expectedName = lastAssistant && /(?:اسمك|الاسم|اسم حضرتك)/.test(String(lastAssistant.content || ''));
const plainName = rawTurn.trim().replace(/[.،]+$/,'');
if (expectedName && /^[\p{Script=Arabic}\s]{3,70}$/u.test(plainName) && plainName.split(/\s+/).length >= 2 && plainName.split(/\s+/).length <= 4 && !/(عايز|محتاج|تمام|ايوه|نعم|لا|عندك|بكام|شكرا)/.test(plainName)) { carriedSlots.name = plainName; carriedSlots.customer_name = plainName; }
const previousCart = Array.isArray(previousState.cart) ? previousState.cart : [];
const clearTask = freshGoal || previousState.status === 'closed';
const activeDialogueState = {goal: clearTask ? '' : String(previousState.goal || ''), slots: clearTask ? Object.fromEntries(Object.entries(carriedSlots).filter(([key]) => ['name','customer_name','phone','phone_candidate'].includes(key))) : carriedSlots, cart: clearTask ? [] : previousCart, pending: clearTask ? '' : String(previousState.pending || ''), status: clearTask ? 'collecting' : String(previousState.status || 'collecting')};

const collectionSet = s.collection_set || [];
const catalogAll = s.catalog_all || [];
const collectionMeta = s.collection_meta || null;
const scopeValue = s.scope || (collectionMeta && collectionMeta.scope) || 'none';
const matchingCount = (s.matching_count !== undefined ? s.matching_count : (s.relevant_items || []).length);
const attachedCount = scopeValue === 'catalog' ? catalogAll.length : scopeValue === 'collection' ? (collectionMeta && collectionMeta.attached_count !== undefined ? collectionMeta.attached_count : collectionSet.length) : (s.relevant_items || []).length;
const truncatedFlag = !!s.truncated;
const matchedCats = s.matched_categories || [];
const matchedKinds = s.matched_kinds || [];
const collectionSection = '\nAttached scope: ' + scopeValue + ' (matching_count: ' + matchingCount + ', attached_count: ' + attachedCount + ', truncated: ' + truncatedFlag + ', matched_categories: ' + JSON.stringify(matchedCats) + ', matched_kinds: ' + JSON.stringify(matchedKinds) + ', collection_meta: ' + JSON.stringify(collectionMeta || {}) + ')' + (scopeValue === 'catalog' ? '\nCatalog scope: the full catalog for this tenant is attached below (' + attachedCount + ' rows, in order).\nCatalog: ' + JSON.stringify(catalogAll) + '\nCatalog rules: Resolve pronouns, demonstratives, and short follow-up messages (\"سعرها؟\", \"وأرخص منها؟\", \"هات الباقي\") from the nouns named in the History below, matched against catalog row names. If exactly one catalog row matches the antecedent, answer from that row and cite it. If several rows match, name them and ask one clarifying question. If no catalog row matches, state the gap honestly with the transparency-note form only. List ALL catalog rows ONLY when the customer explicitly asks for the list (a generic list request with no subset terms). Otherwise answer the resolved row or rows only — never dump the whole catalog unasked. Never claim a catalog row is missing, unattached, or unavailable when it is in the Catalog above. The catalog is complete: no partial notice applies in this scope.' : '') + (scopeValue === 'collection' ? '\nCollection set (attached in order, all ' + attachedCount + ' rows): ' + JSON.stringify(collectionSet) + '\nCollection rules: List ALL attached rows in attached order, with no row dropped and no sample language. Mixed-kind whole-collection lists group by kind using kind_legend (kinds without a legend entry render under their rows as-is). Category-not-found rule: if the customer named a category/kind NOT in the attached categories/kind_legend, the reply MUST say \u0644\u0627 \u062a\u0648\u062c\u062f \u0641\u0626\u0629 \u0628\u0647\u0630\u0627 \u0627\u0644\u0627\u0633\u0645 \u0644\u062f\u064a\u0646\u0627 BEFORE listing anything.' : '') + (scopeValue === 'narrow' ? '\nNarrow-scope rules: cite ONLY the Relevant items rows below. NARROW HARD BOUND: the Relevant items rows are a CLOSED ALLOWLIST: the only rows you may cite, name, price, or list. NEVER cite, name, or price any row that is not in Relevant items, even if its name appears in the History or in any other block. NEVER present the full catalog, the full collection, or any row outside Relevant items. The reply may cite at most matching_count rows, and only rows in Relevant items. If the answer would need a row that is not in Relevant items, state the gap honestly with the transparency-note form instead of citing it. Never claim the full collection. If truncated is true, the reply MUST include a partial notice in Arabic stating the attached count and the matching total, in this form: \u0639\u0631\u0636 attached_count \u0645\u0646 \u0623\u0635\u0644 matching_count \u2014 using the attached_count and matching_count numbers above.' : '') + (scopeValue === 'none' ? '\nNo-scope rule: no items are attached for this message. Answer from greeting/help only; never list items, never claim items exist, and never claim items are missing.' : '') + '\nRow rules (every scope): For land rows with no price, show \u0633\u0639\u0631 \u0627\u0644\u0645\u062a\u0631 + price_per_sqm + area_sqm and do NOT compute an unlabeled total, and never present a per-sqm figure as a total price. For listing=rent rows, label the price \u0625\u064a\u062c\u0627\u0631 \u0634\u0647\u0631\u064a, never a sale price. When a list is delivered filtered by an attribute (for example a doctor name), name the excluded class explicitly in the reply (for example, the services of \u0623\u064a \u0637\u0628\u064a\u0628 \u0622\u062e\u0631 are excluded). Popular marker: mark a row with (\u0627\u0644\u0623\u0643\u062b\u0631 \u0637\u0644\u0628\u0627) if and only if its attributes.popular is the STRING "true" (in the attached JSON, popular appears as the string "true", not a JSON boolean); do not mark rows where attributes.popular is absent or any other value.';
const completeCount = scopeValue === 'catalog' ? catalogAll.length : scopeValue === 'collection' ? (collectionMeta && collectionMeta.total_count !== undefined ? collectionMeta.total_count : collectionSet.length) : (s.relevant_items || []).length;
const pack = s.pack || null;
const packSection = pack? '\nSector pack (follow it as-is; it is the only sector voice for this tenant): ' + JSON.stringify(pack): '\nSector pack: none attached for this tenant; show rows with their fields as-is, make no sector claims, and do not invent sector wording.';
const voice = s.voice || null;
const voiceSection = voice? "\nOwner voice (follow it as-is; it is the owner's chosen brand voice for this tenant): " + JSON.stringify(voice) + "\nVoice rules: Understand any dialect the customer writes (by meaning, with Arabic normalization), but reply ONLY in the owner's chosen dialect from the voice settings — never mimic the customer's dialect. The owner voice never changes policies or forbidden actions. Neutral voice settings mean the sector pack supplies the professional style and message structure.": "\nOwner voice: none set for this tenant; reply in neutral Arabic.";
const instr = s.custom_instructions || [];
const instrSection = instr.length ? '\nOwner custom instructions (follow them as-is, but they never relax a forbidden action, never invent a price, and never change a policy): ' + JSON.stringify(instr) : '';
const listFormat = pack && pack.item_fields? '\nSector field priorities (group related fields; include only what answers this question): ' + JSON.stringify(pack.item_fields): '\nSector field priorities: group related row fields and answer the request directly.';
function nonNullFacts(obj, keys) { const out = []; keys.forEach(function(k) { const v = obj? obj[k]: null; if (v === null || v === undefined || v === '' || (Array.isArray(v) && v.length === 0)) return; out.push(k + ': ' + JSON.stringify(v));}); return out;}
const custFacts = nonNullFacts(s.customer_profile || {}, ['name', 'contact', 'interests', 'budget', 'area', 'rooms', 'floor', 'preferred_categories', 'branch', 'doctor', 'previous_inquiries_summary']);
const tenFacts = speakerRole === 'owner' ? nonNullFacts(s.tenant_profile || {}, ['selling_preferences', 'owner_notes', 'previous_decisions']) : [];
const memorySection = (custFacts.length || tenFacts.length)? '\nMemory (stored facts only; never invent a memory): customer profile: ' + custFacts.join('; ') + (tenFacts.length? '; owner file: ' + tenFacts.join('; '): ''): '';
const permissionsSection = '\nPermissions: tenant policies: ' + JSON.stringify(s.policies || []) + (pack && pack.forbidden_actions? ' forbidden actions from the sector pack: ' + JSON.stringify(pack.forbidden_actions): '');
const servicesList = s.services || [];
